import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // Geometry – high tessellation for displacement
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Base material (PBR)
  const material = new MeshStandardNodeMaterial({
    color: new Color(config.visualSpec?.colors?.paper ?? '#e8ecf2'),
    roughness: 0.6,
    metalness: 0.0,
  });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Keep references for cleanup
  const disposables = {
    textures: [],
    timelines: [],
    primitives: [],
  };

  // Load and apply diffuse texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      disposables.textures.push(tex);
    });
  }

  // Load and apply depth (displacement) texture
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      material.displacementMap = tex;
      material.displacementScale = 0.15; // subtle parallax depth
      material.needsUpdate = true;
      disposables.textures.push(tex);
    });
  }

  // ---------- Interaction Handlers ----------
  const handlers = {};

  // Hover – rise‑in effect (0.15 units up)
  let hoverTl = null;
  handlers.hover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(plane.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    disposables.timelines.push(hoverTl);
  };

  // Hover out – return to original position
  handlers.hoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(plane.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
    });
    disposables.timelines.push(hoverTl);
  };

  // Click – press‑down then emit navigation / select events
  handlers.click = () => {
    // Press‑down feedback
    const pressTl = gsap
      .timeline()
      .to(plane.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      })
      .to(
        plane.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.2,
          ease: 'power2.out',
        },
        '+=0.04'
      );
    disposables.timelines.push(pressTl);

    // Emit selection event
    if (ctx.emit) ctx.emit('hub-features.select');

    // Navigation (placeholder – real URL would come from data binding)
    if (ctx.emit) ctx.emit('navigate', { to: 'hub-features' });
  };

  // Attach handlers to userData
  root.userData.handlers = handlers;

  // ---------- Parallax Cinematic Primitive ----------
  if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
    const prim = ctx.primitives['parallax-scroll'](root, {
      strength: 0.02, // subtle camera‑relative parallax
    });
    disposables.primitives.push(prim);
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose loaded textures
    disposables.textures.forEach((tex) => {
      if (tex?.dispose) tex.dispose();
    });

    // Kill GSAP timelines/tweens
    disposables.timelines.forEach((tl) => {
      if (tl?.kill) tl.kill();
    });
    gsap.killTweensOf(plane.position);
    gsap.killTweensOf(plane.scale);

    // Cleanup primitives
    disposables.primitives.forEach((p) => {
      if (p?.cleanup) p.cleanup();
    });
  };

  return root;
}
